public class Main {
    public static void main(String[] args) {
        LocalDate tanggal = LocalDate.of(2026, 11, 14);
        LocalDateTime mulaiPromo = tanggal.atTime(19, 0);
        LocalDateTime selesaiPromo = mulaiPromo.plusHours(6);
        System.out.println(mulaiPromo);
        System.out.println(selesaiPromo);
        System.out.println(selesaiPromo.getDayOfWeek());
        System.out.println(tanggal.atStartOfDay());
    }
}

