import java.time.*;

public class Main {
    public static void main(String[] args) {
        LocalDateTime pesan = LocalDateTime.of(2026, 6, 30, 22, 15);
        LocalDateTime kirim = pesan.plusHours(3).plusMinutes(30);
        System.out.println(kirim);
        System.out.println(kirim.toLocalDate());
    }
}

